import assert from "node:assert/strict";
import { test } from "node:test";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));

/// The scripts that stand between an agent and a published commit.
///
/// `canonical-push` is the only sanctioned publish path and runs from a
/// pre-push hook, so a tool name it can no longer call does not fail in a
/// terminal where someone is watching — it fails inside git, for every agent
/// in the fleet at once, as a tool-not-found that names neither the cause nor
/// the fix.
const DELIVERY_SCRIPTS = [
  "canonical-push.mjs",
  "claim-gate.mjs",
  "completion-offer.mjs",
  "publication-record.mjs",
  "delivery-queue.mjs",
  "board-health.mjs",
  "stranded-report.mjs",
  "design-audit.mjs",
];

/// Names ADR-0059 retired. Closed and append-only: a name never stops being
/// retired, so this list can go stale only by omission, and an omission costs
/// a missed warning rather than a false one.
const RETIRED = [
  "create_task",
  "decompose_goal",
  "next_task",
  "claim_task",
  "task_scope",
  "existing_work",
  "check_overlap",
  "draft_questions",
  "renew_lease",
  "complete_task",
  "release_task",
  "recover_claim",
  "claim_transfer_history",
  "block_task",
  "reopen_task",
  "abandon_task",
  "resolve_task",
  "ask_question",
  "pending_questions",
  "questions_for_a_human",
  "answer",
  "pause_task",
  "resume_task",
  "task_qa",
  "board",
  "stalled_work",
  "register_design",
  "reconcile_designs",
  "design_board",
  "list_designs",
  "accept_design",
  "reject_design",
  "retire_design",
  "supersede_design",
  "reopen_undecided_design",
  "attribute_design_decision",
  "plan_design_promotion",
  "promote_design",
  "revise_design_promotion",
  "design_promotion",
  "design_materialization_history",
];

/// Only a tool-name position, never an argument value.
///
/// A collapsed verb takes the old name as an argument — `task_query` with
/// `view: "board"`, `task_transition` with `to: "answer"` — so a scan that
/// matches the bare quoted string reports the very migration it is checking
/// for as a violation. A guard that cries wolf is one people learn to skip,
/// which is exactly how the guards this replaces went stale.
const nameSites = (source) => {
  const sites = [];
  const patterns = [
    /name:\s*"([a-z_]+)"/g, // { name: "x", arguments: … }
    /\bcall\(\s*"([a-z_]+)"/g, // call("x", { … })
    /\btool\(\s*"([a-z_]+)"/g, // server.tool("x", { … })
  ];
  for (const pattern of patterns) {
    for (const match of source.matchAll(pattern)) {
      const line = source.slice(0, match.index).split("\n").length;
      sites.push({ name: match[1], line });
    }
  }
  return sites;
};

test("the delivery scripts call no tool name ADR-0059 retired", () => {
  const offences = [];
  for (const script of DELIVERY_SCRIPTS) {
    const source = readFileSync(join(here, script), "utf8");
    for (const { name, line } of nameSites(source)) {
      if (RETIRED.includes(name)) {
        offences.push(`scripts/${script}:${line} calls ${name}`);
      }
    }
  }

  assert.deepEqual(
    offences,
    [],
    `these break when the ADR-0059 removal train lands, and they break inside a git hook:\n  ${offences.join("\n  ")}`,
  );
});

/// The scan has to be able to find something, or it passes by reading nothing.
///
/// This is the failure mode the guard it accompanies actually had: a check
/// whose subject moved kept passing, and passing is indistinguishable from
/// working. Asserting the scan still sees the live call sites means renaming
/// the tool-call shape fails here rather than silently disabling the check.
test("the scan reads the calls it claims to guard", () => {
  const seen = DELIVERY_SCRIPTS.flatMap((script) =>
    nameSites(readFileSync(join(here, script), "utf8")).map(({ name }) => name),
  );

  assert.ok(
    seen.length >= 10,
    `the scan found only ${seen.length} tool calls across the delivery scripts, so it is no longer reading them`,
  );
  for (const expected of ["open_session", "task_query"]) {
    assert.ok(
      seen.includes(expected),
      `the scan cannot see ${expected}, so it is not reading tool calls`,
    );
  }
});
